        # Обрабатываем каждую строку таблицы отдельно
        for row in doc.table:
            if not row.date:
                continue
                
            # Валидация даты без try-except
            row_date = frappe.utils.getdate(row.date)
            if not row_date:
                continue
                
            closest_record = None
            
            # Ищем подходящую запись об утилизации для даты строки
            for utilization in project.custom_project_utilization:
                if not utilization.pu_valid_from:
                    continue
                    
                pu_date = frappe.utils.getdate(utilization.pu_valid_from)
                if not pu_date:
                    continue
                    
                if pu_date <= row_date:
                    closest_pu_date = frappe.utils.getdate(closest_record.pu_valid_from) if closest_record else None
                    if not closest_record or (closest_pu_date and pu_date > closest_pu_date):
                        closest_record = utilization
            
            # Если нашли подходящую запись
            if closest_record:
                row_hours = frappe.utils.flt(row.hours)
                row_utilized = frappe.utils.flt(row.utilized_hours or 0)
                
                if closest_record.get("pu_included") == "Да":
                    # Если включено - обновляем utilized_hours если нужно
                    if row_hours > 0 and not (row_utilized == row_hours):
                        row.utilized_hours = row.hours
                        
                elif closest_record.get("pu_included") == "В рамках плана":
                    is_monthly = closest_record.get("pu_limit") == "В месяц"
                    log_prefix = "месяц" if is_monthly else "итого"
                    log(f"=== Начало обработки строки с датой {row.date} (режим '{log_prefix}') ===")
                    
                    # 1. Поиск плана (ТОЛЬКО ВВЕРХ по иерархии)
                    planned_task = None
                    planned_amounts = []
                    current_task = doc.document_name
                    
                    while current_task is not None and not planned_task:
                        # Проверяем текущую задачу
                        pwe_list = frappe.get_all("Project Work Efforts",
                            filters={
                                "pwe_project": doc.project,
                                "pwe_task": current_task,
                                "pwe_project_role": doc.project_role
                            },
                            fields=["name"],
                            limit=1
                        )
                        
                        if pwe_list and len(pwe_list) > 0:
                            pwe = frappe.get_cached_doc("Project Work Efforts", pwe_list[0]["name"])
                            for amount in pwe.pwe_amount:
                                if is_monthly:
                                    # Для месячного режима проверяем месяц и год
                                    db_month = int(amount.pwea_month) if amount.pwea_month else None
                                    db_year = int(amount.pwea_year) if amount.pwea_year else None
                                    if (db_year is not None and db_year == row_date.year and 
                                        db_month is not None and db_month == row_date.month and 
                                        frappe.utils.flt(amount.pwea_plan or 0) > 0):
                                        planned_task = current_task
                                        planned_amounts = [amount]
                                        break
                                else:
                                    # Для итогового режима собираем все планы
                                    if frappe.utils.flt(amount.pwea_plan or 0) > 0:
                                        planned_task = current_task
                                        planned_amounts.append(amount)
                        
                        # Переходим ТОЛЬКО к родителю
                        if not planned_task:
                            parent = frappe.db.get_value("Task", current_task, "parent_task")
                            current_task = parent if parent else None
                    
                    # 2. Получаем плановые часы
                    plan_hours = 0.0
                    if planned_task:
                        if is_monthly:
                            if planned_amounts:
                                plan_hours = frappe.utils.flt(planned_amounts[0].pwea_plan or 0)
                                log(f"Найден месячный план: {plan_hours} часов в задаче {planned_task}")
                        else:
                            plan_hours = sum([frappe.utils.flt(amount.pwea_plan or 0) for amount in planned_amounts])
                            log(f"Найден итоговый план: {plan_hours} часов (сумма {len(planned_amounts)} периодов) в задаче {planned_task}")
                    else:
                        log("План не найден ни в одной задаче, используем 0 часов")
            
                    # 3. Получаем ВСЕ дочерние задачи для сбора факта (любой уровень вложенности)
                    tasks_for_fact = []
                    if planned_task is not None:
                        # Начинаем с задачи, где найден план
                        tasks_to_process = [planned_task]
                        tasks_for_fact = []
                        while tasks_to_process:
                            current_task = tasks_to_process.pop()
                            tasks_for_fact.append(current_task)
                            # Получаем непосредственных детей
                            children = frappe.get_all("Task",
                                filters={"parent_task": current_task, "project": doc.project},
                                fields=["name"]
                            )
                            tasks_to_process.extend([child["name"] for child in children])
                        log(f"Используем {len(tasks_for_fact)} задач для сбора факта (планирующая + {len(tasks_for_fact)-1} дочерних любого уровня)")
                    else:
                        # Начинаем с текущей задачи
                        tasks_to_process = [doc.document_name]
                        tasks_for_fact = []
                        while tasks_to_process:
                            current_task = tasks_to_process.pop()
                            tasks_for_fact.append(current_task)
                            # Получаем непосредственных детей
                            children = frappe.get_all("Task",
                                filters={"parent_task": current_task, "project": doc.project},
                                fields=["name"]
                            )
                            tasks_to_process.extend([child["name"] for child in children])
                        log(f"План не найден, используем {len(tasks_for_fact)} задач для сбора факта (текущая + {len(tasks_for_fact)-1} дочерних любого уровня)")
            
                    # 4. Собираем фактические часы
                    actual_hours = 0.0
                    if len(tasks_for_fact) > 0:
                        utp_filters = {
                            "document_name": ["in", tasks_for_fact],
                            "project_role": doc.project_role,
                            "name": ["!=", doc.name]  # Исключаем текущий таймшит
                        }
                        
                        if is_monthly:
                            # Используем стандартные функции Frappe для определения диапазона месяца
                            first_day = frappe.utils.formatdate(f"{row_date.year}-{row_date.month:02d}-01", "yyyy-MM-dd")
                            last_day = frappe.utils.get_last_day(row_date)
                            
                            utp_filters["ut_valid_from"] = ["between", [first_day, last_day]]
                        
                        utp_list = frappe.db.get_all("User Timesheet Position", 
                            filters=utp_filters,
                            fields=["name"]
                        )
                        
                        for utp in utp_list:
                            utp_doc = frappe.get_cached_doc("User Timesheet Position", utp["name"])
                            for ts_row in utp_doc.table:
                                if ts_row.date:
                                    ts_date = frappe.utils.getdate(ts_row.date)
                                    if ts_date and (not is_monthly or (ts_date.month == row_date.month and ts_date.year == row_date.year)):
                                        actual_hours = actual_hours + frappe.utils.flt(ts_row.utilized_hours or 0)
                    
                    log(f"Общий факт: {actual_hours} часов")
            
                    # 5. Распределяем остаток
                    remaining_hours = frappe.utils.flt(plan_hours) - frappe.utils.flt(actual_hours)
                    log(f"Остаток часов: {remaining_hours}")
                    
                    if remaining_hours > 0:
                        # Собираем и сортируем строки по дате
                        valid_rows = []
                        for r in doc.table:
                            if r.date:
                                date_val = frappe.utils.getdate(r.date)
                                if date_val:
                                    valid_rows.append({
                                        "row": r,
                                        "date": date_val
                                    })
                        
                        # Сортируем по дате
                        valid_rows.sort(key=lambda x: x["date"])
                        
                        for item in valid_rows:
                            r = item["row"]
                            if remaining_hours <= 0:
                                r.utilized_hours = 0.0
                                continue
                            
                            hours = frappe.utils.flt(r.hours or 0)
                            if hours <= remaining_hours:
                                r.utilized_hours = hours
                                remaining_hours = remaining_hours - hours
                            else:
                                r.utilized_hours = remaining_hours
                                remaining_hours = 0.0
                    else:
                        for r in doc.table:
                            r.utilized_hours = 0.0
                    
                    log(f"=== Окончание обработки строки (режим '{log_prefix}') ===")
                
                else:
                    # Если не включено - обнуляем utilized_hours если нужно
                    if row_utilized != 0:
                        row.utilized_hours = 0

