# Функция для получения портфеля проектов
def get_project_portfolio(project_name, log_date):
    if project_name in cache['project_portfolio']:
        return cache['project_portfolio'][project_name]

    project_doc = frappe.get_cached_doc('Project', project_name)
    portfolio = project_doc.custom_project_portfolio if project_doc.custom_project_portfolio else None

    cache['project_portfolio'][project_name] = portfolio
    return portfolio

def make_doc(doc, template):
    je = frappe.new_doc(doc)
    for k, v in template.items():
        je.set(k, v)
    return je

def find_task_with_plan(project, task, role):
    if (project + task + role) in cache['plan_data']:
        return cache['plan_data'][project + task + role]

    while task:
        pwe = frappe.db.get_value("Project Work Efforts", 
            {"pwe_task": task, "pwe_project": project, "pwe_project_role": role}, 
            ["name"], as_dict=True)

        if pwe:
            doc = frappe.get_cached_doc('Project Work Efforts', pwe.name)
            planned = sum((frappe.utils.flt(r.pwea_plan or 0) for r in doc.pwe_amount), 0.0)

            if planned > 0:
                cache['plan_data'][project + task + role] = task
                return task

        task = frappe.db.get_value('Task', task, 'parent_task')

    return None

def d2s(log_date):
    return frappe.utils.get_datetime_str(log_date)

def get_pt_cost_level(user, project_details, log_date, worker):
    if project_details:
        for project_detail in project_details:
            if project_detail.pt_participant == user and project_detail.pt_cost_level:
                valid_from_ok = True
                valid_for_ok = True

                if project_detail.pt_valid_from:
                    valid_from = frappe.utils.getdate(project_detail.pt_valid_from)
                    valid_from_ok = (log_date >= valid_from)

                if project_detail.pt_valid_for:
                    valid_for = frappe.utils.getdate(project_detail.pt_valid_for)
                    valid_for_ok = (log_date <= valid_for)

                if valid_from_ok and valid_for_ok:
                    log(f"Найден Cost Level {project_detail.pt_cost_level} в проекте для периода {project_detail.pt_valid_from} - {project_detail.pt_valid_for}")
                    return project_detail.pt_cost_level

    if (worker.name + d2s(log_date)) in cache['worker_cost_level']:
        return cache['worker_cost_level'][worker.name + d2s(log_date)]

    if worker.get('worker_level'):
        closest_level = None
        for level in worker.worker_level:
            if level.wl_valid_from:
                level_date = frappe.utils.getdate(level.wl_valid_from)
                if level_date <= log_date:
                    if not closest_level or level_date > frappe.utils.getdate(closest_level.wl_valid_from):
                        closest_level = level

        if closest_level:
            cache['worker_cost_level'][worker.name + d2s(log_date)] = closest_level.wl_cosl_level
            return closest_level.wl_cosl_level

def get_cost_rate(pt_cost_level, log_date):
    if (pt_cost_level + d2s(log_date)) in cache['cost_rate']:
        return cache['cost_rate'][pt_cost_level + d2s(log_date)]

    cost_level = frappe.get_cached_doc('Cost Level', pt_cost_level)
    closest_rate = None
    closest_date = None

    for rate in cost_level.rate_table:
        if rate.rt_valid_from:
            rate_date = frappe.utils.getdate(rate.rt_valid_from)
            if rate_date <= log_date:
                if not closest_date or rate_date > closest_date:
                    closest_date = rate_date
                    closest_rate = rate.rt_rate

    cache['cost_rate'][pt_cost_level + d2s(log_date)] = closest_rate
    return closest_rate

def get_account_for_date(accounts_table, worker_type, log_date):
    closest_row = None
    closest_match_type_row = None

    for row in accounts_table:
        if row.ac_valid_from:
            row_date = frappe.utils.getdate(row.ac_valid_from)
            if row_date <= log_date:
                if row.ac_type == worker_type:
                    if not closest_match_type_row or row_date > frappe.utils.getdate(closest_match_type_row.ac_valid_from):
                        closest_match_type_row = row
                elif not row.ac_type:
                    if not closest_row or row_date > frappe.utils.getdate(closest_row.ac_valid_from):
                        closest_row = row

    if closest_match_type_row:
        log(f"Найден account (по типу {worker_type}): {closest_match_type_row.ac_account}")
        return closest_match_type_row.ac_account
    elif closest_row:
        log(f"Найден account (без типа): {closest_row.ac_account}")
        return closest_row.ac_account

    return None

# Тикет -- https://erp.dinord.ru/app/issue/ISS-2025-01841 -- вариант без try-except
def get_account_for_task_hierarchy(current_task_name, worker_type, log_date, project):
    if (current_task_name + d2s(log_date)) in cache['account_data']:
        return cache['account_data'][current_task_name + d2s(log_date)]

    while current_task_name:
        log(f"Проверяем account на уровне задачи {current_task_name}")
        task = frappe.get_cached_doc('Task', current_task_name, ignore_permissions=True)

        if task.get('custom_account_table'):
            account = get_account_for_date(task.custom_account_table, worker_type, log_date)

            if account:
                cache['account_data'][current_task_name + d2s(log_date)] = account
                return account

        current_task_name = task.parent_task

    if (project.name + d2s(log_date)) in cache['account_data']:
        return cache['account_data'][project.name + d2s(log_date)]

    if project.get('custom_account_table'):
        log("Проверяем account на уровне проекта")
        account = get_account_for_date(project.custom_account_table, worker_type, log_date)

        if account:
            cache['account_data'][project.name + d2s(log_date)] = account
            return account

    return None

