def get_closest_business_area(table, log_date):
    closest_rows = []
    if table:
        closest_date = None
        for row in table:
            if row.valid_from:
                row_date = frappe.utils.getdate(row.valid_from)
                if row_date <= log_date:
                    if not closest_date or row_date > closest_date:
                        closest_date = row_date
                        closest_rows.clear()
                    if row_date == closest_date:
                        closest_rows.append( row )
    return closest_rows

def get_business_area(project, current_task_name, log_date):
    if ("task$" + current_task_name + d2s(log_date)) in cache['business_area']:
        return cache['business_area']["task$" + current_task_name + d2s(log_date)]

    closest_rows = []    

    while current_task_name:
        log(f"Проверяем business area на уровне задачи {current_task_name}")
        task = frappe.get_cached_doc('Task', current_task_name, ignore_permissions=True)

        closest_rows = get_closest_business_area(task.get('custom_business_area'), log_date)

        if len( closest_rows ):
            cache['business_area']["task$" + current_task_name + d2s(log_date)] = closest_rows
            return closest_rows

        current_task_name = task.parent_task

    log("Проверяем business area на уровне проекта")
    if (project.name + d2s(log_date)) in cache['business_area']:
        return cache['business_area'][project.name + d2s(log_date)]

    closest_rows = get_closest_business_area(project.get('custom_business_area'), log_date)

    if not len( closest_rows ):
        closest_rows.append( make_doc('Cost Business Area', { 'valid_from': log_date, 'business_area': None, 'percent': 100 } ) )

    cache['business_area'][project.name + d2s(log_date)] = closest_rows
    return closest_rows

def get_project_cost_center(project, log_date):
    if (project.name + d2s(log_date)) in cache['project_cost_center']:
        return cache['project_cost_center'][project.name + d2s(log_date)]

    if project.get('custom_cost_center_table'):
        closest_row = None
        for row in project.custom_cost_center_table:
            if row.cct_valid_from:
                row_date = frappe.utils.getdate(row.cct_valid_from)
                if row_date <= log_date:
                    if not closest_row or row_date > frappe.utils.getdate(closest_row.cct_valid_from):
                        closest_row = row

        if closest_row:
            cache['project_cost_center'][project.name + d2s(log_date)] = closest_row.cct_cost_center
            return closest_row.cct_cost_center

    return None

def get_worker_cost_center(worker, log_date):
    if (worker.name + d2s(log_date)) in cache['worker_cost_center']:
        return cache['worker_cost_center'][worker.name + d2s(log_date)]

    if worker.get('cost_center_table'):
        closest_row = None
        for row in worker.cost_center_table:
            if row.cct_valid_from:
                row_date = frappe.utils.getdate(row.cct_valid_from)
                if row_date <= log_date:
                    if not closest_row or row_date > frappe.utils.getdate(closest_row.cct_valid_from):
                        closest_row = row

        if closest_row:
            cache['worker_cost_center'][worker.name + d2s(log_date)] = closest_row.cct_cost_center
            return closest_row.cct_cost_center

    return None

def get_employee(worker):
    if worker.wuser in cache['employee']:
        return cache['employee'][worker.wuser]

    employee = frappe.db.get_value('Employee', 
                    {'user_id': worker.wuser, 'status': 'Active'}, 
                    ['name', 'company', 'payroll_cost_center', 'department'], 
                    as_dict=True)

    cache['employee'][worker.wuser] = employee
    return employee

def get_employee_cost_center(worker):
    employee = get_employee(worker)

    if employee.name in cache['employee_cost_center']:
        return cache['employee_cost_center'][employee.name]

    cost_center_employee = employee.get('payroll_cost_center')

    if not cost_center_employee and employee.department:
        cost_center_employee = frappe.db.get_value('Department', employee.department, 'payroll_cost_center')

    cache['employee_cost_center'][employee.name] = cost_center_employee
    return cost_center_employee

def get_data_for_party(worker, project_company):
    if worker.wtype == "Employee":
        employee = get_employee(worker)
        if employee and employee.company:
            company_account = frappe.db.get_value('Company', 
                                                employee.company, 
                                                'default_payroll_payable_account')
            if company_account:
                return {
                    'account': company_account,
                    'party_type': 'Employee',
                    'party': employee.name
                }
    elif worker.wtype == "Supplier":
        supplier = frappe.db.sql("""
            SELECT parent FROM `tabPortal User` 
            WHERE parenttype = 'Supplier' AND user = %s
            LIMIT 1
        """, worker.wuser, as_dict=True)

        if supplier:
            supplier_name = supplier[0].parent
            supplier_doc = frappe.get_cached_doc('Supplier', supplier_name)

            # 1. Ищем account в Supplier для компании проекта
            account = None
            for acc in supplier_doc.accounts:
                if acc.company == project_company:
                    account = acc.account
                    break

            # 2. Если не нашли в Supplier, ищем в Supplier Group
            if not account and supplier_doc.supplier_group:
                supplier_group = frappe.get_cached_doc('Supplier Group', supplier_doc.supplier_group)
                for acc in supplier_group.accounts:
                    if acc.company == project_company:
                        account = acc.account
                        break

            # 3. Если account не найден ни в Supplier, ни в Supplier Group - ошибка
            if not account:
                frappe.throw(f"Не найден account для компании {project_company} у поставщика {supplier_name} и его группы {supplier_doc.supplier_group}")

            return {
                'account': account,
                'party_type': 'Supplier',
                'party': supplier_name
            }
    return None

def get_round_off_account(company):
