            #'party': worker.name
        }
        log("Round Off Row: " + frappe.utils.cstr(round_row))
        journal_entry.append('accounts', round_row)

        journal_entry.save(ignore_permissions=True)
        log(f"Добавлена корректировка баланса на сумму {round(difference, 2)}")

