def build_response(success, message="", positions=None, duplicates=None, invalid=None):
    positions = positions or []
    duplicates = duplicates or []
    invalid = invalid or []
    return {
        "success": success,
        "message": message,
        "data": {
            "positions": positions,
            "copied_count": len(positions),
            "duplicates_count": len(duplicates),
            "invalid_count": len(invalid),
            "duplicate_items": duplicates,
            "invalid_items": invalid
        }
    }


def get_current_timesheet_name():
    doc_data = frappe.form_dict.get("doc")

    if not doc_data and getattr(frappe, "request", None) and getattr(frappe.request, "data", None):
        request_data = frappe.request.data
        if hasattr(request_data, "get"):
            doc_data = request_data.get("doc")

    if not doc_data:
        return None

    if isinstance(doc_data, str):
        name_start = doc_data.find('"name":"') + 8
        name_end = doc_data.find('"', name_start)
        if name_start > 7 and name_end > name_start:
            return doc_data[name_start:name_end]
        return None

    if isinstance(doc_data, dict):
        return doc_data.get("name")

    return None


